import{_ as e,o as s,c as n,a0 as i}from"./chunks/framework.bcCluOOn.js";const u=JSON.parse('{"title":"Syntax Basics","description":"","frontmatter":{},"headers":[],"relativePath":"specification/syntax.md","filePath":"specification/syntax.md"}'),t={name:"specification/syntax.md"};function o(l,a,p,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="syntax-basics" tabindex="-1">Syntax Basics <a class="header-anchor" href="#syntax-basics" aria-label="Permalink to &quot;Syntax Basics&quot;">​</a></h1><p>AAYU is designed to be highly readable, favoring English-like keywords over excessive punctuation.</p><h2 id="statements-and-termination" tabindex="-1">Statements and Termination <a class="header-anchor" href="#statements-and-termination" aria-label="Permalink to &quot;Statements and Termination&quot;">​</a></h2><p>All statements and declarative blocks in AAYU must end with a period (<code>.</code>).</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>number max_users is 100.</span></span>
<span class="line"><span>show max_users.</span></span></code></pre></div><h2 id="blocks" tabindex="-1">Blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;Blocks&quot;">​</a></h2><p>Blocks of code, such as <code>task</code> definitions, <code>entity</code> bodies, or <code>if</code> statements, begin with a declaration and are closed with the <code>end.</code> keyword.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task greet with name.</span></span>
<span class="line"><span>    show &quot;Hello, &quot; + name.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="variables-and-assignment" tabindex="-1">Variables and Assignment <a class="header-anchor" href="#variables-and-assignment" aria-label="Permalink to &quot;Variables and Assignment&quot;">​</a></h2><p>Variables in AAYU are strongly typed. They are declared using their type, followed by the identifier, the <code>is</code> keyword, and the initial value.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text message is &quot;Welcome to AAYU&quot;.</span></span>
<span class="line"><span>number count is 42.</span></span>
<span class="line"><span>boolean is_active is true.</span></span></code></pre></div><p>Reassignment is done using the <code>is</code> keyword without the type declaration (if the variable already exists in scope), or by updating map properties.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2><p>Comments begin with the <code>#</code> symbol and extend to the end of the line.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># This is a comment</span></span>
<span class="line"><span>number age is 30. # This is an inline comment</span></span></code></pre></div><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><p>AAYU supports standard operators, often utilizing English words for boolean logic to maintain readability.</p><h3 id="arithmetic" tabindex="-1">Arithmetic <a class="header-anchor" href="#arithmetic" aria-label="Permalink to &quot;Arithmetic&quot;">​</a></h3><ul><li><code>+</code> (Addition, String Concatenation)</li><li><code>-</code> (Subtraction)</li><li><code>*</code> (Multiplication)</li><li><code>/</code> (Division)</li></ul><h3 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h3><ul><li><code>equal to</code> (==)</li><li><code>not_equal to</code> (!=)</li><li><code>&lt;</code> (Less than)</li><li><code>&gt;</code> (Greater than)</li></ul><h3 id="logical" tabindex="-1">Logical <a class="header-anchor" href="#logical" aria-label="Permalink to &quot;Logical&quot;">​</a></h3><ul><li><code>and</code> (Logical AND)</li><li><code>or</code> (Logical OR)</li><li><code>not</code> (Logical NOT)</li></ul><h2 id="control-flow" tabindex="-1">Control Flow <a class="header-anchor" href="#control-flow" aria-label="Permalink to &quot;Control Flow&quot;">​</a></h2><h3 id="if-else-statements" tabindex="-1">If / Else Statements <a class="header-anchor" href="#if-else-statements" aria-label="Permalink to &quot;If / Else Statements&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>number score is 85.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if score &gt; 80.</span></span>
<span class="line"><span>    show &quot;Excellent&quot;.</span></span>
<span class="line"><span>else.</span></span>
<span class="line"><span>    show &quot;Good&quot;.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h3 id="loops" tabindex="-1">Loops <a class="header-anchor" href="#loops" aria-label="Permalink to &quot;Loops&quot;">​</a></h3><p>AAYU supports <code>while</code> loops and <code>foreach</code> loops for iterating over lists.</p><p><strong>While Loop:</strong></p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>number i is 0.</span></span>
<span class="line"><span>while i &lt; 5.</span></span>
<span class="line"><span>    show i.</span></span>
<span class="line"><span>    number i is i + 1.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><p><strong>Foreach Loop:</strong></p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list names is [&quot;Alice&quot;, &quot;Bob&quot;, &quot;Charlie&quot;].</span></span>
<span class="line"><span>foreach name in names.</span></span>
<span class="line"><span>    show name.</span></span>
<span class="line"><span>end.</span></span></code></pre></div>`,32)])])}const m=e(t,[["render",o]]);export{u as __pageData,m as default};
